<#
.SYNOPSIS
    Antigravity (CLI / Desktop / IDE) — 提示词精简 (4档) 与 百万上下文解锁 (512K / 900K) 一键工具
    支持 GitHub 远程一键加载 (irm ... | iex)、命令行 -- 参数直达、以及交互式数字键菜单。

.DESCRIPTION
    一、提示词精简档位 (--prompt 1|2|3|4|restore)
      [1] 1档 · 仅去广告        : 仅清空 slash_commands.tmpl 与 plugins.tmpl（去除 /goal、/boost 推销）
      [2] 2档 · 原版最大化精简  : 清空 7 个冗余/致幻槽位（artifacts/brain、KI 强制前置等），保留原版核心指令
      [3] 3档 · 全量重构版      : 清空 7 槽 + 全面替换为 Amp × Argon 外科手术重构版
      [4] 4档 · 原版+防幻觉增强 : 在 2 档原版基础上，注入 Amp 最佳实践与 Argon 防幻觉护栏（推荐）
      [restore]                 : 恢复原版默认提示词

    二、上下文窗口解锁档位 (--context 512k|900k|restore)
      [512k]    : 将 Cortex GetCheckpointConfig 中的 256K/128K 封顶提升至 512,000 并同步配置
      [900k]    : NOP 跳过 GetCheckpointConfig 中的 0x3e800/0x1f400 封顶指令，释放完整 ~983K (1M) 物理窗口
      [restore] : 恢复原版默认上下文限制

.EXAMPLE
    # 1. 直接启动（进入数字键交互菜单）：
    .antigravity-patch.ps1

    # 2. 通过 -- 参数快速执行（如 4档提示词 + 900k 上下文解锁）：
    .antigravity-patch.ps1 --prompt 4 --context 900k

    # 3. 一键全部恢复官方默认状态：
    .antigravity-patch.ps1 --restore

    # 4. 托管到 GitHub 后远程一键加载：
    irm https://raw.githubusercontent.com/<user>/<repo>/main/antigravity-patch.ps1 | iex
#>

function Invoke-AntigravityPatch {
    [CmdletBinding()]
    param(
        [Parameter(ValueFromRemainingArguments = $true)]
        [string[]]$ForwardArgs
    )

    $ErrorActionPreference = "Stop"

    # 若同目录下存在 patch-antigravity.mjs 则直接调用，否则从内嵌载荷释放到 TEMP 执行（完美支持 irm ... | iex 单文件无依赖加载）
    if ($PSScriptRoot) {
        $LocalMjs = Join-Path $PSScriptRoot "patch-antigravity.mjs"
        if (Test-Path $LocalMjs) {
            & node $LocalMjs @ForwardArgs
            return
        }
    }

    $TempMjs = Join-Path $env:TEMP "antigravity-surgical-patcher.mjs"
    $PayloadB64 = ""
    $Bytes = [System.Convert]::FromBase64String($PayloadB64)
    [System.IO.File]::WriteAllBytes($TempMjs, $Bytes)
    & node $TempMjs @ForwardArgs
}

Invoke-AntigravityPatch @args
